Data.Script:
var a = String(vars.answer == null ? "" : vars.answer).trim().toLowerCase();
var dmg = Number(vars.fireDamage) || 0;
var final = 0, text;
if (vars.hitCount === 0) text = "The Fireball hit nobody.";
else if (["yes", "y", "tak", "t", "full"].indexOf(a) >= 0) { final = dmg; text = "The GM applied " + dmg + " fire damage to " + vars.hitCount + " creature(s)."; }
else if (["half", "h", "pol", "pół", "polowa", "połowa"].indexOf(a) >= 0) { final = Math.floor(dmg / 2); text = "The GM applied half (" + final + ") to " + vars.hitCount + " creature(s)."; }
else if (a) text = "The GM didn't apply the damage.";
else text = "The GM didn't answer: no damage applied.";
return { damage: final, apply: final > 0 ? 1 : 0, result: text };
